//! Fixed-record parsing only. No serving fixture, new issuance API or wire format.
use super::*;
use crate::fusefss_backend::{
    conversions as c,
    wire::{ImportGuard, Reader},
};
use crate::shared_rescale_reference::Context;
use crate::shared_wide_product::ring::{TripleShare, TRIPLE_BYTES};
use std::sync::atomic::Ordering;
use zeroize::Zeroize;

// Frozen literal little-endian record, not generated by the writer under test.
const GOLDEN: [u8; 24] = [
    1, 0, 0, 0, 0, 0, 0, 0, 0x23, 0, 0, 0, 0, 0, 0, 0, 0xff, 0, 0, 0, 0, 0, 0, 0,
];

fn encode(words: &[u64; 3]) -> Vec<u8> {
    words.iter().flat_map(|word| word.to_le_bytes()).collect()
}

// Historical parser, independently retained as an oracle; no new helper call.
fn legacy(input: &mut Reader<'_>, bits: u8) -> Result<Zeroizing<[u64; 3]>, Error> {
    Ok(Zeroizing::new([
        input.word(bits)?,
        input.word(bits)?,
        input.word(bits)?,
    ]))
}

fn tail(input: &Reader<'_>) -> Vec<u8> {
    let mut reader = input.fork();
    let mut remaining = Vec::new();
    while let Ok(byte) = reader.take(1) {
        remaining.extend_from_slice(byte);
    }
    remaining
}

#[test]
fn literal_bytes_endian_width_boundaries_and_original_writer_match() {
    assert_eq!(
        &*decode_fixed_words::<3>(&GOLDEN, 8).unwrap(),
        &[1, 0x23, 0xff]
    );
    assert!(decode_fixed_words::<3>(&GOLDEN, 7).is_err());
    assert!(decode_fixed_words::<0>(&[], 8).unwrap().is_empty());
    for bits in [1, 2, 7, 8, 31, 50] {
        let mask = (1u64 << bits) - 1;
        let expected = [0, mask / 3, mask];
        let bytes = encode(&expected);
        let fixed = decode_fixed_words::<3>(&bytes, bits).unwrap();
        assert_eq!(&*fixed, &expected);
        let mut reader = Reader::new(&bytes);
        let triple = TripleShare::read_material(&mut reader, bits).unwrap();
        reader.finish().unwrap();
        let mut exported = Vec::new();
        triple.write_material(&mut exported);
        assert_eq!(exported, bytes);
    }
    let mut reader = Reader::new(&GOLDEN);
    let triple = TripleShare::read_material(&mut reader, 8).unwrap();
    let mut exported = Vec::new();
    triple.write_material(&mut exported);
    assert_eq!(exported, GOLDEN);
}

#[test]
fn fixed_geometry_preflight_and_each_noncanonical_word_reject_without_masking() {
    for length in 0..=32 {
        if length != TRIPLE_BYTES {
            assert!(matches!(
                decode_fixed_words::<3>(&vec![0; length], 8),
                Err(Error::Context)
            ));
        }
    }
    for bits in [0, 51, 64, 255] {
        assert!(matches!(
            decode_fixed_words::<3>(&GOLDEN, bits),
            Err(Error::Context)
        ));
    }
    for bits in [1, 8, 31, 50] {
        for index in 0..3 {
            let mut words = [0; 3];
            words[index] = 1u64 << bits;
            assert!(matches!(
                decode_fixed_words::<3>(&encode(&words), bits),
                Err(Error::Context)
            ));
        }
    }
}

#[test]
fn short_invalid_and_trailing_records_preserve_legacy_failed_cursor_and_error() {
    let mut cases: Vec<Vec<u8>> = (0..24).map(|length| GOLDEN[..length].to_vec()).collect();
    cases.push(GOLDEN.to_vec());
    for index in 0..3 {
        let mut words = [1, 2, 3];
        words[index] = 256;
        cases.push(encode(&words));
    }
    let mut trailing = GOLDEN.to_vec();
    trailing.extend_from_slice(b"following-public-record");
    cases.push(trailing);
    for bytes in &cases {
        for prefix in [0, 8, 17] {
            let mut prefixed = vec![0x5a; prefix];
            prefixed.extend_from_slice(bytes);
            for bits in [0, 1, 7, 8, 50, 51, 64, 255] {
                let (mut old, mut new) = (Reader::new(&prefixed), Reader::new(&prefixed));
                old.take(prefix).unwrap();
                new.take(prefix).unwrap();
                let expected = legacy(&mut old, bits);
                let actual = TripleShare::read_material(&mut new, bits);
                match (expected, actual) {
                    (Ok(expected), Ok(actual)) => {
                        let mut exported = Vec::new();
                        actual.write_material(&mut exported);
                        assert_eq!(exported, encode(&expected));
                    }
                    (Err(expected), Err(actual)) => assert_eq!(actual, expected),
                    _ => panic!("legacy fixed-record result differs"),
                }
                assert_eq!(tail(&new), tail(&old));
                assert_eq!(new.fork().finish(), old.fork().finish());
            }
        }
    }
    // A triple can prefix other fields; complete-envelope readers still reject
    // trailing data. Do not consume a following lane/record inside this leaf.
    let mut bytes = GOLDEN.to_vec();
    bytes.push(0);
    let mut input = Reader::new(&bytes);
    let _ = TripleShare::read_material(&mut input, 8).unwrap();
    assert_eq!(input.finish(), Err(Error::Context));
}

fn legacy_finish(words: &[u64; 3], role: u8, d: u64, e: u64, mask: u64) -> u64 {
    words[2]
        .wrapping_add(d.wrapping_mul(words[1]))
        .wrapping_add(e.wrapping_mul(words[0]))
        .wrapping_add(if role == 0 { d.wrapping_mul(e) } else { 0 })
        & mask
}

#[test]
fn both_recipient_words_openings_and_reconstruction_match_independent_legacy_algebra() {
    for bits in [1, 8, 31, 50] {
        let mask = (1u64 << bits) - 1;
        let (a, b) = (5 & mask, 3 & mask);
        let left = [2 & mask, 4 & mask, 7 & mask];
        let right = [
            a.wrapping_sub(left[0]) & mask,
            b.wrapping_sub(left[1]) & mask,
            a.wrapping_mul(b).wrapping_sub(left[2]) & mask,
        ];
        let (left_bytes, right_bytes) = (encode(&left), encode(&right));
        let old_left = legacy(&mut Reader::new(&left_bytes), bits).unwrap();
        let old_right = legacy(&mut Reader::new(&right_bytes), bits).unwrap();
        let new_left = TripleShare::read_material(&mut Reader::new(&left_bytes), bits).unwrap();
        let new_right = TripleShare::read_material(&mut Reader::new(&right_bytes), bits).unwrap();
        let (x, y) = (9 & mask, 11 & mask);
        let own = [6 & mask, 2 & mask];
        let peer = [x.wrapping_sub(own[0]) & mask, y.wrapping_sub(own[1]) & mask];
        let first = new_left.open(own[0], own[1]).unwrap();
        let second = new_right.open(peer[0], peer[1]).unwrap();
        assert_eq!(
            &*first,
            &[
                own[0].wrapping_sub(left[0]) & mask,
                own[1].wrapping_sub(left[1]) & mask
            ]
        );
        assert_eq!(
            &*second,
            &[
                peer[0].wrapping_sub(right[0]) & mask,
                peer[1].wrapping_sub(right[1]) & mask
            ]
        );
        let d = first[0].wrapping_add(second[0]) & mask;
        let e = first[1].wrapping_add(second[1]) & mask;
        let (output_a, output_b) = (
            new_left.finish(0, &first, &second).unwrap(),
            new_right.finish(1, &second, &first).unwrap(),
        );
        assert_eq!(output_a, legacy_finish(&old_left, 0, d, e, mask));
        assert_eq!(output_b, legacy_finish(&old_right, 1, d, e, mask));
        assert_eq!(
            output_a.wrapping_add(output_b) & mask,
            x.wrapping_mul(y) & mask
        );
    }
}

#[test]
fn both_leaf_decoders_already_heap_free_packet_copy_and_admission_stay_fallible() {
    let size = ENVELOPE_BYTES + GOLDEN.len();
    let source = Budget::new(size).unwrap();
    let packet = packet(
        b"FIXED001",
        2,
        0,
        [1; 32],
        [2; 32],
        GOLDEN.len(),
        &source,
        |out| {
            out.extend_from_slice(&GOLDEN);
            Ok(())
        },
    )
    .unwrap();
    source.fail_after.store(0, Ordering::SeqCst);
    let body = open(&packet, b"FIXED001", 2, 0, [1; 32], [2; 32], GOLDEN.len()).unwrap();
    let mut fixed = decode_fixed_words::<3>(body, 8).unwrap();
    let _old = legacy(&mut Reader::new(body), 8).unwrap();
    let _new = TripleShare::read_material(&mut Reader::new(body), 8).unwrap();
    assert_eq!(source.fail_after.load(Ordering::SeqCst), 0);
    assert_eq!(source.used_bytes(), size);
    fixed.zeroize();
    assert_eq!(&*fixed, &[0; 3]);
    assert_eq!(source.used_bytes(), size);
    let destination = Budget::new(size).unwrap();
    destination.fail_after.store(0, Ordering::SeqCst);
    assert!(matches!(
        MaterialPacket::from_bytes(packet.as_bytes(), &destination),
        Err(Error::Allocation)
    ));
    assert_eq!(destination.used_bytes(), 0);
    let short = Budget::new(size - 1).unwrap();
    short.fail_after.store(0, Ordering::SeqCst);
    assert!(matches!(
        MaterialPacket::from_bytes(packet.as_bytes(), &short),
        Err(Error::Resource)
    ));
    assert_eq!(short.fail_after.load(Ordering::SeqCst), 0);
    assert_eq!(short.used_bytes(), 0);
    assert!(matches!(
        MaterialPacket::from_bytes(packet.as_bytes(), &source),
        Err(Error::Resource)
    ));
    drop(packet);
    assert_eq!(source.used_bytes(), 0);
}

fn spec() -> c::Spec {
    c::Spec {
        input_bits: 8,
        output_bits: 8,
        lanes: 1,
        operation: c::Operation::Multiply,
        source_digest: [17; 32],
        profile_digest: [18; 32],
    }
}
fn context() -> Context {
    Context {
        plan: [21; 32],
        session: [22; 32],
        operation: [23; 32],
        first_tensor_index: 0,
    }
}

#[test]
fn full_import_keeps_preflight_admission_replay_and_packet_owner_retirement() {
    let source = Budget::new(MAX_ALLOCATION_BYTES).unwrap();
    let [party, other] = c::issue(spec(), context(), &source).unwrap();
    drop(other);
    let packet = party.export_material().unwrap();
    let nonce = packet.nonce();
    let replay = MaterialPacket::from_bytes(packet.as_bytes(), &source).unwrap();
    let guard_bytes = crate::fusefss_backend::wire::ImportGuardLayout::legacy(1)
        .unwrap()
        .reservation_bytes();
    let needed = c::resources(spec()).unwrap().party_reservation_bytes;
    let worker = Budget::new(guard_bytes + needed - 1).unwrap();
    let mut guard = ImportGuard::new(1, &worker).unwrap();
    worker.fail_after.store(0, Ordering::SeqCst);
    assert!(matches!(
        c::Party::import_material(spec(), context(), 0, nonce, packet, &mut guard, &worker),
        Err(Error::Resource)
    ));
    assert_eq!(worker.used_bytes(), guard_bytes);
    assert_eq!(worker.fail_after.load(Ordering::SeqCst), 0);
    assert!(matches!(
        c::Party::import_material(spec(), context(), 0, nonce, replay, &mut guard, &worker),
        Err(Error::Consumed)
    ));
    assert_eq!(source.used_bytes(), 0);
    drop(guard);
    assert_eq!(worker.used_bytes(), 0);
}

#[test]
fn unchanged_party_vector_factory_still_fails_after_fixed_preflight_and_refunds() {
    let source = Budget::new(MAX_ALLOCATION_BYTES).unwrap();
    let worker = Budget::new(MAX_ALLOCATION_BYTES).unwrap();
    let mut guard = ImportGuard::new(1, &worker).unwrap();
    let baseline = worker.used_bytes();
    let [party, other] = c::issue(spec(), context(), &source).unwrap();
    drop(other);
    let packet = party.export_material().unwrap();
    let nonce = packet.nonce();
    worker.fail_after.store(0, Ordering::SeqCst);
    // Fixed-word preflight has no factory. The existing admitted party-lane
    // vector still reaches its allocation hook, with no fallback or quote cut.
    assert!(matches!(
        c::Party::import_material(spec(), context(), 0, nonce, packet, &mut guard, &worker),
        Err(Error::Allocation)
    ));
    assert_eq!(worker.used_bytes(), baseline);
    assert_eq!(worker.fail_after.load(Ordering::SeqCst), 0);
    assert_eq!(source.used_bytes(), 0);
    drop(guard);
    assert_eq!(worker.used_bytes(), 0);
}

#[test]
fn failed_context_precedes_allocation_and_unwind_cannot_reset_claim_or_leak_owner() {
    let source = Budget::new(MAX_ALLOCATION_BYTES).unwrap();
    let worker = Budget::new(MAX_ALLOCATION_BYTES).unwrap();
    let mut guard = ImportGuard::new(4, &worker).unwrap();
    let baseline = worker.used_bytes();
    for panic in [false, true] {
        let [party, other] = c::issue(spec(), context(), &source).unwrap();
        drop(other);
        let packet = party.export_material().unwrap();
        let nonce = packet.nonce();
        let replay = MaterialPacket::from_bytes(packet.as_bytes(), &source).unwrap();
        if panic {
            let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                let mut imported = c::Party::import_material(
                    spec(),
                    context(),
                    0,
                    nonce,
                    packet,
                    &mut guard,
                    &worker,
                )
                .unwrap();
                imported.cancel();
                std::panic::panic_any(8819u64);
            }));
            assert_eq!(*result.unwrap_err().downcast::<u64>().unwrap(), 8819);
        } else {
            worker.fail_after.store(0, Ordering::SeqCst);
            let bad = Context {
                operation: [24; 32],
                ..context()
            };
            assert!(matches!(
                c::Party::import_material(spec(), bad, 0, nonce, packet, &mut guard, &worker),
                Err(Error::Context)
            ));
            assert_eq!(worker.fail_after.load(Ordering::SeqCst), 0);
            worker.fail_after.store(-1, Ordering::SeqCst);
        }
        assert_eq!(worker.used_bytes(), baseline);
        assert!(matches!(
            c::Party::import_material(spec(), context(), 0, nonce, replay, &mut guard, &worker),
            Err(Error::Consumed)
        ));
        assert_eq!(source.used_bytes(), 0);
    }
    drop(guard);
    assert_eq!(worker.used_bytes(), 0);
}
